//! Combine Python type stubs with docstrings from the installed bindings.

#![cfg_attr(test, allow(clippy::panic))]

use std::{env, error::Error, fs, path::Path, process::Command};

use pyo3::{prelude::*, types::PyList};

const HEADER: &str = "# Generated by cargo run -p delta-arrow-reader-python --example generate-api-docs.\n\
    # Do not edit. Update the Rust binding comments or the Python type stubs instead.\n\n";

fn set_docstring(
    ast: &Bound<'_, PyModule>,
    node: &Bound<'_, PyAny>,
    doc: &Bound<'_, PyAny>,
) -> PyResult<()> {
    let body = node.getattr("body")?.cast_into::<PyList>()?;
    if !ast.call_method1("get_docstring", (node,))?.is_none() {
        body.del_item(0)?;
    }
    if doc.is_truthy()? {
        body.insert(
            0,
            ast.call_method1("Expr", (ast.call_method1("Constant", (doc,))?,))?,
        )?;
    }
    Ok(())
}

fn render(ast: &Bound<'_, PyModule>, stub: &str, module: &Bound<'_, PyAny>) -> PyResult<String> {
    let tree = ast.call_method1("parse", (stub,))?;
    for node in tree.getattr("body")?.try_iter()? {
        let node = node?;
        if !node.is_instance(&ast.getattr("ClassDef")?)? {
            continue;
        }
        let native = module.getattr(node.getattr("name")?.extract::<String>()?)?;
        set_docstring(ast, &node, &native.getattr("__doc__")?)?;
        for member in node.getattr("body")?.try_iter()? {
            let member = member?;
            if member.is_instance(&ast.getattr("FunctionDef")?)? {
                let name: String = member.getattr("name")?.extract()?;
                // PyO3 puts constructor documentation on the class.
                let doc = if name == "__init__" {
                    ast.py().None().into_bound(ast.py())
                } else {
                    native.getattr(name)?.getattr("__doc__")?
                };
                set_docstring(ast, &member, &doc)?;
            }
        }
    }
    let source: String = ast.call_method1("unparse", (tree,))?.extract()?;
    Ok(format!("{HEADER}{source}\n"))
}

fn write_or_check(
    ast: &Bound<'_, PyModule>,
    output: &Path,
    rendered: &str,
    check: bool,
) -> Result<(), Box<dyn Error>> {
    if check {
        let current = match fs::read_to_string(output) {
            Ok(value) => value,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => String::new(),
            Err(error) => return Err(error.into()),
        };
        let syntax = |source: &str| -> PyResult<String> {
            ast.call_method1("dump", (ast.call_method1("parse", (source,))?,))?
                .extract()
        };
        if syntax(&current)? != syntax(rendered)? {
            return Err("Python API documentation is stale. Rebuild the Python bindings, then run cargo run --locked -p delta-arrow-reader-python --example generate-api-docs -- --python <installed-python>".into());
        }
        println!("Python API documentation is current.");
    } else {
        if let Some(parent) = output.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(output, rendered)?;
        println!("Updated {}", output.display());
    }
    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut arguments = env::args().skip(1);
    let mut check = false;
    let mut python = String::from("python");
    while let Some(argument) = arguments.next() {
        match argument.as_str() {
            "--check" => check = true,
            "--python" => python = arguments.next().ok_or("--python requires an interpreter")?,
            _ => return Err("usage: generate-api-docs [--check] [--python INTERPRETER]".into()),
        }
    }
    // Probe the selected installation, without importing its virtualenv's stdlib into embedded Python.
    let probe = Command::new(python)
        .args([
            "-I",
            "-c",
            "import json, sysconfig; import delta_arrow_reader.delta_arrow_reader as native; print(json.dumps([sysconfig.get_path('purelib'), native.__file__]))",
        ])
        .output()?;
    if !probe.status.success() {
        return Err(format!(
            "cannot locate installed bindings: {}",
            String::from_utf8_lossy(&probe.stderr)
        )
        .into());
    }
    let paths = String::from_utf8(probe.stdout)?;
    let package = Path::new(env!("CARGO_MANIFEST_DIR"));
    let stub = fs::read_to_string(package.join("delta_arrow_reader.pyi"))?;
    let output =
        package.join("../delta-arrow-reader-core/docs/python_api/delta_arrow_reader/__init__.pyi");
    Python::initialize();
    Python::attach(|py| {
        let [site_packages, module_path]: [String; 2] = py
            .import("json")?
            .call_method1("loads", (paths,))?
            .extract()?;
        py.import("sys")?
            .getattr("path")?
            .cast_into::<PyList>()
            .map_err(PyErr::from)?
            .insert(0, site_packages)?;
        let util = py.import("importlib.util")?;
        let spec = util.call_method1(
            "spec_from_file_location",
            ("delta_arrow_reader", module_path),
        )?;
        let module = util.call_method1("module_from_spec", (&spec,))?;
        spec.getattr("loader")?
            .call_method1("exec_module", (&module,))?;
        let ast = py.import("ast")?;
        write_or_check(&ast, &output, &render(&ast, &stub, &module)?, check)
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use pyo3::{exceptions::PyAttributeError, types::PyDict};

    #[test]
    fn docstrings_replace_old_text_without_changing_types() -> PyResult<()> {
        Python::initialize();
        Python::attach(|py| {
            let ast = py.import("ast")?;
            let namespace = py.import("types")?.getattr("SimpleNamespace")?;
            let module = namespace.call0()?;
            let class = namespace.call0()?;
            class.setattr("__doc__", "Native table documentation.")?;
            let method = namespace.call0()?;
            let doc = "Read rows.\n\nExamples:\n    print(\"\"\"rows\"\"\")\n    path = \"a\\b\"";
            method.setattr("__doc__", doc)?;
            class.setattr("read", method)?;
            module.setattr("Table", class)?;
            let stub = "class Table:\n    '''Old class doc.'''\n    def __init__(self, path: str) -> None: ...\n    @property\n    def read(self, *, limit: int | None = None) -> list[str]:\n        '''Old method doc.'''\n        ...\n";
            let rendered = render(&ast, stub, &module)?;
            let tree = ast.call_method1("parse", (&rendered,))?;
            let table = tree.getattr("body")?.get_item(0)?;
            assert_eq!(
                ast.call_method1("get_docstring", (&table,))?
                    .extract::<String>()?,
                "Native table documentation."
            );
            let members = table.getattr("body")?;
            assert!(
                ast.call_method1("get_docstring", (members.get_item(1)?,))?
                    .is_none()
            );
            let kwargs = PyDict::new(py);
            kwargs.set_item("clean", false)?;
            assert_eq!(
                ast.call_method("get_docstring", (members.get_item(2)?,), Some(&kwargs))?
                    .extract::<String>()?,
                doc
            );
            let original = ast.call_method1("parse", (stub,))?;
            for tree in [&tree, &original] {
                for node in ast.call_method1("walk", (tree,))?.try_iter()? {
                    let node = node?;
                    if node.is_instance(&ast.getattr("ClassDef")?)?
                        || node.is_instance(&ast.getattr("FunctionDef")?)?
                    {
                        set_docstring(&ast, &node, &py.None().into_bound(py))?;
                    }
                }
            }
            assert_eq!(
                ast.call_method1("dump", (tree,))?.extract::<String>()?,
                ast.call_method1("dump", (original,))?.extract::<String>()?
            );
            let error =
                render(&ast, "class Table:\n    def missing(self): ...", &module).unwrap_err();
            assert!(error.is_instance_of::<PyAttributeError>(py));
            Ok(())
        })
    }

    #[test]
    fn stale_checks_never_rewrite_output_and_ignore_formatting() -> Result<(), Box<dyn Error>> {
        Python::initialize();
        Python::attach(|py| {
            let temporary = py
                .import("tempfile")?
                .getattr("TemporaryDirectory")?
                .call0()?;
            let directory: String = temporary.getattr("name")?.extract()?;
            let output = Path::new(&directory).join("output.pyi");
            let ast = py.import("ast")?;
            assert!(write_or_check(&ast, &output, "value: int\n", true).is_err());
            assert!(!output.exists());
            write_or_check(&ast, &output, "value: int\n", false)?;
            write_or_check(&ast, &output, "# header\nvalue : int\n", true)?;
            assert!(write_or_check(&ast, &output, "value: str\n", true).is_err());
            assert_eq!(fs::read_to_string(&output)?, "value: int\n");
            temporary.call_method0("cleanup")?;
            Ok(())
        })
    }
}
